<template><div class="app-container"><el-button type="primary" @click="openAdd">新增购买套餐</el-button><el-table v-loading="loading" :data="rows" class="mt16"><el-table-column prop="packageName" label="套餐名称"/><el-table-column prop="credits" label="算力"/><el-table-column prop="bonusCredits" label="赠送"/><el-table-column prop="price" label="售价"/><el-table-column prop="description" label="说明"/><el-table-column label="操作" width="150"><template #default="s"><el-button link type="primary" @click="openEdit(s.row)">编辑</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table><el-dialog v-model="visible" :title="editing ? '编辑购买套餐' : '新增购买套餐'"><el-form :model="form" label-width="90px"><el-form-item label="套餐名称"><el-input v-model="form.packageName"/></el-form-item><el-form-item label="算力"><el-input-number v-model="form.credits" :min="1"/></el-form-item><el-form-item label="售价"><el-input-number v-model="form.price" :min="0" :precision="2"/></el-form-item><el-form-item label="赠送算力"><el-input-number v-model="form.bonusCredits" :min="0"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup name="VizoraPackage">
import { listPackages, addPackage, updatePackage, delPackage } from '@/api/vizora/operation'
const { proxy }=getCurrentInstance(),rows=ref([]),loading=ref(false),visible=ref(false),editing=ref(false),form=reactive({packageId:undefined,packageName:'',credits:1000,price:9.9,bonusCredits:0,enabled:1,sortOrder:0,description:''})
async function load(){loading.value=true;try{const r=await listPackages();rows.value=r.rows||[]}finally{loading.value=false}}function openAdd(){editing.value=false;Object.assign(form,{packageId:undefined,packageName:'',credits:1000,price:9.9,bonusCredits:0,enabled:1,sortOrder:0,description:''});visible.value=true}function openEdit(row){editing.value=true;Object.assign(form,row);visible.value=true}async function save(){editing.value?await updatePackage(form):await addPackage(form);visible.value=false;load()}async function remove(row){await proxy.$modal.confirm(`确认删除套餐 ${row.packageName} 吗？`);await delPackage(row.packageId);proxy.$modal.msgSuccess('删除成功');load()}load()
</script>
<style scoped>.app-container>.el-button{margin-bottom:16px}.mt16{margin-top:16px}</style>
